source='''from collections import Counter

def transform(grid):
    rows, cols = len(grid), len(grid[0])
    background = {color for color, _ in Counter(cell for row in grid for cell in row).most_common(3)}
    seen = set()
    largest = (0, None)
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color in background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            size = 0
            while stack:
                rr, cc = stack.pop()
                size += 1
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            if size > largest[0]:
                largest = (size, color)
    color = largest[1]
    return [[color] * 3 for _ in range(3)]
'''
